// Masks GetUserDefaultLCID with 0x1FF and maps English, German, French, Italian, Spanish, and
// Russian primary-language values to telephone country codes 44, 49, 33, 39, 34, and 7. Other
// values return zero.

dword __cdecl Locale_GetDefaultTelephoneCountryCode(void)

{
  LCID userLocaleId;
  uint primaryLanguageId;
  dword telephoneCountryCode;
  
  userLocaleId = GetUserDefaultLCID();
  primaryLanguageId = userLocaleId & 0x1ff;
  if (primaryLanguageId == 9) {
    telephoneCountryCode = 0x2c;
  }
  else if (primaryLanguageId == 7) {
    telephoneCountryCode = 0x31;
  }
  else if (primaryLanguageId == 0xc) {
    telephoneCountryCode = 0x21;
  }
  else if (primaryLanguageId == 0x10) {
    telephoneCountryCode = 0x27;
  }
  else if (primaryLanguageId == 10) {
    telephoneCountryCode = 0x22;
  }
  else if (primaryLanguageId == 0x19) {
    telephoneCountryCode = 7;
  }
  else {
    telephoneCountryCode = 0;
  }
  return telephoneCountryCode;
}



// Copies exactly 0x40 bytes from the fixed UTF-16 label L"Computer", including trailing zero
// padding, into destination.

void Locale_CopyDefaultComputerLabelUtf16(word *destination)

{
  int copyDwordsRemaining;
  word *sourceCursor;
  
  sourceCursor = g_DefaultComputerLabelUtf16;
  for (copyDwordsRemaining = 0x10; copyDwordsRemaining != 0;
      copyDwordsRemaining = copyDwordsRemaining + -1) {
    *(undefined4 *)destination = *(undefined4 *)sourceCursor;
    sourceCursor = sourceCursor + 2;
    destination = destination + 2;
  }
  return;
}



// WARNING: Removing unreachable block (ram,0x00587379)
// Executes CPUID leaf 1, sets g_CpuFeatureFlags bit 0 when EDX bit 23 reports MMX support, and
// returns constant 5.

dword __cdecl CPU_DetectFeatures(void)

{
  int cpuidVersionInfo;
  
  cpuidVersionInfo = cpuid_Version_info(1);
  if ((*(uint *)(cpuidVersionInfo + 8) & 0x800000) != 0) {
    g_CpuFeatureFlags = g_CpuFeatureFlags | 1;
  }
  return 5;
}



